16→
17→/**
18→ * List all failed tasks with optional pagination and filtering
19→ */
20→export async function listFailedTasks(
21→  params?: { skip?: number; limit?: number; task_name?: string }
22→): Promise<ApiResult<FailedTaskListResponse>> {
23→  return apiClient.get<FailedTaskListResponse>(BASE_PATH, params);
24→}
25→
26→/**
27→ * Get a single failed task by ID with full detail
28→ */
29→export async function getFailedTask(
30→  id: number
31→): Promise<ApiResult<FailedTaskResponse>> {
32→  return apiClient.get<FailedTaskResponse>(`${BASE_PATH}/${id}`);
33→}
34→
35→/**
36→ * Retry a failed task by re-dispatching the Celery task
37→ */
38→export async function retryFailedTask(
39→  id: number
40→): Promise<ApiResult<FailedTaskResponse>> {
41→  return apiClient.post<FailedTaskResponse>(`${BASE_PATH}/${id}/retry`);
42→}
